// Validate HomeLab Info (@Home_Lab_info_bot, id 8967925790) webhook secret token,
// restrict Approve/Reject to the owner's private chat, and verify HMAC callback signature.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const headerToken = String(headers['x-telegram-bot-api-secret-token'] || '');
const expectedToken = String($env.HOMELAB_INFO_WEBHOOK_SECRET || '');

if (!headerToken || !expectedToken || headerToken.length !== expectedToken.length || !crypto.timingSafeEqual(Buffer.from(headerToken), Buffer.from(expectedToken))) {
  throw new Error('Unauthorized HomeLab Info webhook secret token');
}

const cb = body.callback_query;
if (!cb || !String(cb.data || '').startsWith('hlc-pub|')) {
  return [];
}

const senderBot = cb.message?.from;
if (senderBot?.id && Number(senderBot.id) !== 8967925790) {
  throw new Error('Callback did not originate from HomeLab Info bot (8967925790)');
}
if (cb.message?.chat?.type && cb.message.chat.type !== 'private') {
  throw new Error('Approvals restricted to owner private chat');
}

const ownerId = String($env.HOMELAB_OWNER_TELEGRAM_ID || '');
if (!ownerId || String(cb.from?.id) !== ownerId || String(cb.message?.chat?.id) !== ownerId) {
  throw new Error('Unauthorized Telegram user or chat ID');
}

const parts = String(cb.data || '').split('|');
if (parts.length !== 4) {
  throw new Error('Malformed hlc-pub callback_data');
}
const [ns, action, shortSlug, sig] = parts;
if (ns !== 'hlc-pub' || !['approve', 'reject'].includes(action)) {
  return [];
}
const expectedSig = crypto.createHmac('sha256', $env.HOMELAB_INFO_CALLBACK_SECRET).update(`hlc-pub|${action}|${shortSlug}`, 'utf8').digest('hex').slice(0, 16);
if (sig.length !== expectedSig.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
  throw new Error('Invalid callback_data HMAC signature');
}

return [{
  json: {
    decision: action,
    approved: action === 'approve',
    shortSlug,
    reviewerId: cb.from.id,
    callbackQueryId: cb.id,
    messageId: cb.message?.message_id
  }
}];

